// Counts and retained cache slots only; not timings or full operation counts.
fn width_metrics(p:&RecoveryProducts)->[usize;7]{let q=p.inner.borrow();let mut live=q.polynomial.as_ref().map_or(0,|v|v.len());let mut capacity=q.polynomial.as_ref().map_or(0,|v|v.capacity());if let Some(g)=&q.progression{live+=g.samples.len()+g.weights.len();capacity+=g.samples.capacity()+g.weights.capacity();}[q.polynomial_setups,q.progression_setups,q.evaluation_batches,q.convolution_calls,q.query_trees,live,capacity]}
fn width_add(a:&mut[usize;7],b:[usize;7]){for j in 0..7{a[j]+=b[j];}}
fn width_plan_checks(){
 let(mut panels,mut coefficients)=(0,0);let(mut old_initial,mut plan_initial,mut old_final,mut plan_final,mut separate_final)=([0;7],[0;7],[0;7],[0;7],[0;7]);
 for(r,m)in[(281u64,35usize),(1009,63),(2017,63),(2521,315)]{let mm=2*m;let eta=(2..r).find(|&z|pow(z,mm as u64,r)==1&&(1..mm).all(|j|pow(z,j as u64,r)!=1)).unwrap();for cap in [1usize,2,7,16,64]{
  let old=RecoveryProducts::new(r,m,cap).unwrap();let plan=RecoveryProducts::planned_doubling(r,m,cap).unwrap();let separate=RecoveryProducts::new(r,m,cap).unwrap();let separate2=RecoveryProducts::new(r,mm,cap).unwrap();let ow=old.inner.borrow().width;let pw=plan.inner.borrow().width;assert!(pw>=ow&&pw<=cap);assert_eq!(pw,separate2.inner.borrow().width);assert!(plan.inner.borrow().polynomial.is_none());
  let a=rescue_stream_values(r,m,cap,&old);assert_eq!(a,rescue_stream_values(r,m,cap,&plan));assert_eq!(a,rescue_stream_values(r,m,cap,&separate));coefficients+=a.len();let oi=width_metrics(&old);let pi=width_metrics(&plan);width_add(&mut old_initial,oi);width_add(&mut plan_initial,pi);
  let stream=StreamModes::new(r,mm,eta,mm,r as usize,cap).unwrap();let o2=old.for_doubled(&stream).unwrap();let p2=plan.for_doubled(&stream).unwrap();assert!(std::ptr::eq(&*plan.inner,&*p2.inner));let a=rescue_stream_values(r,mm,cap,&o2);assert_eq!(a,rescue_stream_values(r,mm,cap,&p2));assert_eq!(a,rescue_stream_values(r,mm,cap,&separate2));coefficients+=a.len();let of=width_metrics(&old);let pf=width_metrics(&plan);let mut sf=width_metrics(&separate);width_add(&mut sf,width_metrics(&separate2));width_add(&mut old_final,of);width_add(&mut plan_final,pf);width_add(&mut separate_final,sf);
  println!("width_panel r={r} m={m} block_cap={cap} old_width={ow} planned_width={pw} no_rescue_old={oi:?} no_rescue_planned={pi:?} doubled_old={of:?} doubled_planned={pf:?} doubled_separate={sf:?}");panels+=1;
 }}
 let mut rejects=0;for(r,m,cap)in[(0u64,3usize,7usize),(41,4,7),(41,3,7),(41,5,0)]{assert!(RecoveryProducts::planned_doubling(r,m,cap).is_err());rejects+=1;}
 println!("width_summary panels={panels} coefficient_equalities={coefficients} rejected_controls={rejects} metrics=[polynomial_setups,grid_setups,batches,convolutions,query_trees,live_slots,capacity_slots] no_rescue_old={old_initial:?} no_rescue_planned={plan_initial:?} doubled_old={old_final:?} doubled_planned={plan_final:?} doubled_separate={separate_final:?}");
 let(p,a,b,r,base)=(257,1,7,281,[1,3]);let curve=group::Curve::new(p,a,b);let bp=group::Point{x:base[0],y:base[1]};let source=source::Source::new(p,a,b,r,base,64).unwrap();let extra:Vec<_>=(0..17).collect();
 for m in [5usize,35]{let z=(2..r).find(|&z|pow(z,m as u64,r)==1&&(1..m).all(|j|pow(z,j as u64,r)!=1)).unwrap();let modes=StreamModes::new(r,m,z,m,256,7).unwrap();let caps:&[usize]=if m==5{&[8,10,16,20,32,64]}else{&[64,128]};for &cap in caps{let(mut calls,mut recovered,mut rescue_routes)=(0,0,0);let(mut old_work,mut plan_work)=([0;7],[0;7]);let(mut old_max,mut plan_max)=(0,0);
  for k in 0..r{let target=multiple(curve,bp,k);let oc=RecoveryModes::from_modes(&modes).unwrap();let pc=RecoveryModes::planned_width(&modes).unwrap();let old=oc.recover_shared_rescue(&source,curve,bp,target,&[1,r-1,2,3],cap,&extra,128).unwrap();let new=pc.recover_shared_rescue(&source,curve,bp,target,&[1,r-1,2,3],cap,&extra,128).unwrap();assert_eq!(old.0,new.0);assert_eq!(old.1.calls,new.1.calls);assert_eq!(old.2,new.2);if let Some(v)=new.0{assert_eq!(v,k);recovered+=1;}calls+=new.1.calls;rescue_routes+=usize::from(new.2=="doubled-phase");let om=width_metrics(&oc.products);let pm=width_metrics(&pc.products);old_max=old_max.max(om[6]);plan_max=plan_max.max(pm[6]);width_add(&mut old_work,om);width_add(&mut plan_work,pm);
  }
  println!("width_public cases={r} m={m} cap={cap} source_calls={calls} recovered={recovered} rescue_routes={rescue_routes} old_metrics={old_work:?} planned_metrics={plan_work:?} max_retained_capacity_old={old_max} max_retained_capacity_planned={plan_max}");
 }
 for k in [0,17,140]{let target=multiple(curve,bp,k);for radii in [[1,r-1,2,3],[1,2,3,4]]{let a=modes.recover_planned_width(&source,curve,bp,target,&radii,64,&extra,128).unwrap();let b=modes.recover_shared_rescue(&source,curve,bp,target,&radii,64,&extra,128).unwrap();assert_eq!(a.0,b.0);assert_eq!(a.1.calls,b.1.calls);assert_eq!(a.2,b.2);}}
 }
 println!("width_wrapper_checks=12");
}
